#include <LiquidCrystal.h>

/*
  =====================================================
                      FOOD QUEST
             ARDUINO CONTROLLER - V2
  =====================================================

  LCD 1602A comum, SEM I2C
  Potenciometro B10K para contraste
  Joystick
  2 botoes
  Clique do joystick = VOLTAR
  LED RGB com controle completo de cores

  RGB:
  R = D9
  G = D10
  B = D11

  Valores RGB podem ir de 0 ate 255.
*/


/* =====================================================
   LCD 1602A
   RS, E, D4, D5, D6, D7
===================================================== */

LiquidCrystal lcd(5, 6, 7, 8, 12, 13);


/* =====================================================
   JOYSTICK
===================================================== */

const int JOY_X = A0;
const int JOY_Y = A1;

const int BUTTON_BACK = 4;


/* =====================================================
   BOTOES
===================================================== */

const int BUTTON_OK   = 2;
const int BUTTON_HINT = 3;


/* =====================================================
   LED RGB
===================================================== */

const int LED_RED   = 9;
const int LED_GREEN = 10;
const int LED_BLUE  = 11;


/* =====================================================
   JOYSTICK
===================================================== */

const int LOW_LIMIT  = 300;
const int HIGH_LIMIT = 700;

bool joystickReleased = true;


/* =====================================================
   BOTOES / DEBOUNCE
===================================================== */

bool oldOK   = HIGH;
bool oldHint = HIGH;
bool oldBack = HIGH;

unsigned long lastButtonTime = 0;

const unsigned long debounceTime = 180;


/* =====================================================
   SERIAL
===================================================== */

String serialLine = "";


/* =====================================================
   SETUP
===================================================== */

void setup() {

  Serial.begin(9600);


  /* BOTOES */

  pinMode(
    BUTTON_OK,
    INPUT_PULLUP
  );

  pinMode(
    BUTTON_HINT,
    INPUT_PULLUP
  );

  pinMode(
    BUTTON_BACK,
    INPUT_PULLUP
  );


  /* LED RGB */

  pinMode(
    LED_RED,
    OUTPUT
  );

  pinMode(
    LED_GREEN,
    OUTPUT
  );

  pinMode(
    LED_BLUE,
    OUTPUT
  );


  setRGB(
    0,
    0,
    0
  );


  /* LCD */

  lcd.begin(
    16,
    2
  );

  showLCD(
    "FOOD QUEST",
    "AGUARDANDO..."
  );


  /* Pequena animacao RGB ao iniciar */

  setRGB(255, 0, 0);
  delay(200);

  setRGB(0, 255, 0);
  delay(200);

  setRGB(0, 0, 255);
  delay(200);

  setRGB(0, 0, 0);


  delay(300);

}


/* =====================================================
   LOOP
===================================================== */

void loop() {

  readJoystick();

  readButtons();

  readPhone();

}


/* =====================================================
   JOYSTICK
===================================================== */

void readJoystick() {

  int x =
    analogRead(
      JOY_X
    );

  int y =
    analogRead(
      JOY_Y
    );


  /*
    JOYSTICK NO CENTRO
  */

  if(
    x > LOW_LIMIT &&
    x < HIGH_LIMIT &&
    y > LOW_LIMIT &&
    y < HIGH_LIMIT
  ) {

    joystickReleased = true;

    return;

  }


  /*
    ESPERA VOLTAR AO CENTRO
  */

  if(
    !joystickReleased
  ) {

    return;

  }


  /*
    CIMA
  */

  if(
    y < LOW_LIMIT
  ) {

    Serial.println(
      "JOY_UP"
    );

    joystickReleased = false;

    return;

  }


  /*
    BAIXO
  */

  if(
    y > HIGH_LIMIT
  ) {

    Serial.println(
      "JOY_DOWN"
    );

    joystickReleased = false;

    return;

  }


  /*
    ESQUERDA
  */

  if(
    x < LOW_LIMIT
  ) {

    Serial.println(
      "JOY_LEFT"
    );

    joystickReleased = false;

    return;

  }


  /*
    DIREITA
  */

  if(
    x > HIGH_LIMIT
  ) {

    Serial.println(
      "JOY_RIGHT"
    );

    joystickReleased = false;

    return;

  }

}


/* =====================================================
   BOTOES
===================================================== */

void readButtons() {

  bool nowOK =
    digitalRead(
      BUTTON_OK
    );

  bool nowHint =
    digitalRead(
      BUTTON_HINT
    );

  bool nowBack =
    digitalRead(
      BUTTON_BACK
    );


  /*
    BOTAO A
    OK / SELECIONAR
  */

  if(
    oldOK == HIGH &&
    nowOK == LOW &&
    canPress()
  ) {

    Serial.println(
      "BUTTON_OK"
    );

    buttonPressed();

  }


  /*
    BOTAO B
    DICA
  */

  if(
    oldHint == HIGH &&
    nowHint == LOW &&
    canPress()
  ) {

    Serial.println(
      "BUTTON_HINT"
    );

    buttonPressed();

  }


  /*
    CLIQUE DO JOYSTICK
    VOLTAR
  */

  if(
    oldBack == HIGH &&
    nowBack == LOW &&
    canPress()
  ) {

    Serial.println(
      "BUTTON_BACK"
    );

    buttonPressed();

  }


  oldOK =
    nowOK;

  oldHint =
    nowHint;

  oldBack =
    nowBack;

}


/* =====================================================
   DEBOUNCE
===================================================== */

bool canPress() {

  return
    millis() -
    lastButtonTime
    >
    debounceTime;

}


void buttonPressed() {

  lastButtonTime =
    millis();

}


/* =====================================================
   RECEBER COMANDOS
===================================================== */

void readPhone() {

  while(
    Serial.available()
  ) {

    char c =
      Serial.read();


    if(
      c == '\n'
    ) {

      serialLine.trim();


      if(
        serialLine.length() > 0
      ) {

        processPhoneCommand(
          serialLine
        );

      }


      serialLine = "";

    }

    else {

      serialLine += c;

    }

  }

}


/* =====================================================
   COMANDOS RECEBIDOS
===================================================== */

void processPhoneCommand(
  String command
) {


  /*
    LCD

    Exemplo:

    LCD|RAFAEL:|SUA VEZ!
  */

  if(
    command.startsWith(
      "LCD|"
    )
  ) {

    processLCDCommand(
      command
    );

    return;

  }


  /*
    COMPATIBILIDADE
    COM COMANDOS ANTIGOS
  */

  if(
    command == "LED|GREEN"
  ) {

    setRGB(
      0,
      255,
      0
    );

    return;

  }


  if(
    command == "LED|RED"
  ) {

    setRGB(
      255,
      0,
      0
    );

    return;

  }


  if(
    command == "LED|OFF"
  ) {

    setRGB(
      0,
      0,
      0
    );

    return;

  }


  /*
    NOVO SISTEMA RGB

    Formato:

    RGB|R|G|B

    Exemplos:

    RGB|255|0|0
    = vermelho

    RGB|0|255|0
    = verde

    RGB|0|0|255
    = azul

    RGB|255|255|0
    = amarelo

    RGB|255|0|255
    = magenta

    RGB|0|255|255
    = ciano

    RGB|255|100|0
    = laranja

    RGB|255|20|147
    = rosa

    RGB|128|0|255
    = violeta
  */

  if(
    command.startsWith(
      "RGB|"
    )
  ) {

    processRGBCommand(
      command
    );

    return;

  }

}


/* =====================================================
   COMANDO RGB
===================================================== */

void processRGBCommand(
  String command
) {

  int first =
    command.indexOf('|');

  int second =
    command.indexOf(
      '|',
      first + 1
    );

  int third =
    command.indexOf(
      '|',
      second + 1
    );


  if(
    first < 0 ||
    second < 0 ||
    third < 0
  ) {

    return;

  }


  int red =
    command.substring(
      first + 1,
      second
    ).toInt();


  int green =
    command.substring(
      second + 1,
      third
    ).toInt();


  int blue =
    command.substring(
      third + 1
    ).toInt();


  red =
    constrain(
      red,
      0,
      255
    );

  green =
    constrain(
      green,
      0,
      255
    );

  blue =
    constrain(
      blue,
      0,
      255
    );


  setRGB(
    red,
    green,
    blue
  );

}


/* =====================================================
   CONTROLAR RGB
===================================================== */

void setRGB(
  int red,
  int green,
  int blue
) {

  analogWrite(
    LED_RED,
    red
  );

  analogWrite(
    LED_GREEN,
    green
  );

  analogWrite(
    LED_BLUE,
    blue
  );

}


/* =====================================================
   LCD
===================================================== */

void processLCDCommand(
  String command
) {

  /*
    Formato:

    LCD|LINHA 1|LINHA 2
  */

  int first =
    command.indexOf('|');

  int second =
    command.indexOf(
      '|',
      first + 1
    );


  if(
    first < 0 ||
    second < 0
  ) {

    return;

  }


  String line1 =
    command.substring(
      first + 1,
      second
    );


  String line2 =
    command.substring(
      second + 1
    );


  showLCD(
    line1,
    line2
  );

}


/* =====================================================
   ESCREVER NO LCD
===================================================== */

void showLCD(
  String line1,
  String line2
) {

  lcd.clear();


  /*
    LINHA 1
  */

  lcd.setCursor(
    0,
    0
  );


  if(
    line1.length() > 16
  ) {

    line1 =
      line1.substring(
        0,
        16
      );

  }


  lcd.print(
    line1
  );


  /*
    LINHA 2
  */

  lcd.setCursor(
    0,
    1
  );


  if(
    line2.length() > 16
  ) {

    line2 =
      line2.substring(
        0,
        16
      );

  }


  lcd.print(
    line2
  );

}
